<?php
namespace App\Game; use App\DB;
final class AchievementService { public const ALL=['first_10k'=>['emoji'=>'💰','name'=>'اولین ۱۰ هزار','reward'=>1000,'cond'=>['worth'=>10000]],'first_business'=>['emoji'=>'🏢','name'=>'اولین کسب‌وکار','reward'=>2500,'cond'=>['flag'=>'first_business']],'first_car'=>['emoji'=>'🚗','name'=>'اولین ماشین','reward'=>1000,'cond'=>['flag'=>'first_car']],'homeowner'=>['emoji'=>'🏠','name'=>'صاحب‌خانه','reward'=>3000,'cond'=>['flag'=>'homeowner']],'millionaire'=>['emoji'=>'👑','name'=>'میلیونر','reward'=>50000,'cond'=>['worth'=>1000000]],'famous'=>['emoji'=>'🔥','name'=>'مشهور','reward'=>20000,'cond'=>['fame'=>500]],'level10'=>['emoji'=>'⭐','name'=>'لول ۱۰','reward'=>15000,'cond'=>['level'=>10]],'level20'=>['emoji'=>'🌟','name'=>'لول ۲۰','reward'=>60000,'cond'=>['level'=>20]],'trusted'=>['emoji'=>'🤝','name'=>'شریک قابل اعتماد','reward'=>5000,'cond'=>['transfers'=>5]],'big_spender'=>['emoji'=>'💎','name'=>'خریدار حرفه‌ای','reward'=>8000,'cond'=>['flag'=>'big_spender']]];
 public static function check(array $user,?string $flag=null):array{$fresh=PlayerService::findByTg((int)$user['telegram_id'])??$user;$worth=(int)$fresh['cash']+(int)$fresh['bank'];$s=DB::pdo()->prepare("SELECT COUNT(*) FROM transactions WHERE user_id=? AND type='transfer_out'");$s->execute([$fresh['id']]);$trans=(int)$s->fetchColumn();$out=[];foreach(self::ALL as $key=>$a){$q=DB::pdo()->prepare('SELECT 1 FROM player_achievements WHERE user_id=? AND achievement_key=?');$q->execute([$fresh['id'],$key]);if($q->fetch())continue;$c=$a['cond'];$type=array_key_first($c);$ok=match($type){'worth'=>$worth>=$c[$type],'fame'=>(int)$fresh['fame']>=$c[$type],'level'=>(int)$fresh['level']>=$c[$type],'transfers'=>$trans>=$c[$type],'flag'=>$flag===$c[$type],default=>false};if($ok){DB::pdo()->prepare('INSERT INTO player_achievements (user_id,achievement_key,unlocked_at) VALUES (?,?,?)')->execute([$fresh['id'],$key,time()]);EconomyService::earn($fresh,(int)$a['reward'],'جایزه دستاورد: '.$a['name']);$out[]=$a;}}return $out;}}
